        text: "你说先保人，别的慢慢来，先请安保，调查的事往后放。这句话说出口的时候，你自己也知道慢意味着什么：意味着有些线索会先一步凉掉，有些人会先一步察觉，有些门会先一步关紧。可你还是这么定了，因为眼下更要紧的，是那两个人今晚能不能睡着，能不能不再听见楼道里有脚步就坐直。安保第二天就到，两个人的班次、路线、交接都写得很细，连孩子放学走哪一条路都问清楚了，回来要在群里报一声。她看见门口多出来的人，没说什么，也没道谢，只是那天晚上睡得出奇早，房间的灯九点就灭了。你翻着那份还没来得及做的调查清单，一项项都是空的，空得让你有点心虚，像是把最要紧的一半先搁下了。你把它折起来，决定明天再想。夜里楼下的车灯偶尔扫过窗帘，一道一道地过，你在黑暗里睁着眼，把可能慢掉的每一步都想了一遍，等了好一会儿才睡。她那天晚上睡得很沉，你在客厅坐了一会儿，听见她房间一直没有动静，才回的自己屋。你想，慢就慢一点，慢总比出事强。这个念头你后来在很多地方用过，有的地方管用，有的地方不管用，可你那一次，是真的这么想的，想完心里还踏实了一点。",
