        cond: null,
        text: "律师事务所在这栋写字楼的十七层，走廊铺着厚地毯，走上去几乎没有声音，连说话都不自觉压低了。你把她送到门口就停住了，没有跟进去，只说你在外面等，有需要随时叫你。她在门口站了两秒，理了理衣角，又看一眼手里的文件夹，深吸一口气，自己推门进去。你在走廊的椅子上坐下来，翻手机，其实一个字也没看进去。隔着那扇隔音不太好的门，能隐约听见律师的声音，平稳、专业、不夹一句多余的话，还有她偶尔的回答，很轻，轻得你要竖起耳朵才听得见。中途你听见她笑了一声，很短，像说了一句连自己都觉得意外的话。两个多小时后门开了，她出来，把那个文件夹抱在胸前，抱得很紧，像是怕它飞掉。她的眼睛是红的，但整个人比进去时松弛，走路的时候步子也稳，甚至比来时快。她走到你面前，站定，说了一句话，声音里有一种你第一次听见的东西。她说，原来这些是可以问的。没有别的，就这一句。你没有接话，只是站起来，和她并排往电梯走。电梯下行的时候，她一直看着文件夹的封面，指尖在边角上压了又压，一个字也没有再说。楼层数字一格一格往下跳，你看着她的侧脸，忽然觉得今天这两个小时，比你替她跑的任何一趟路都值。",
