        text: "你没让她把话铺开，而是拿出纸，列了三条能马上做的事：先固定几笔必要支出、再确认孩子的学籍不受影响、最后分出一笔钱应对催告。你把顺序讲清楚，讲她能控制的部分，哪些今天就能办，哪些要等。她听得很认真，听到最后一条还问了两个细节，你一一作答，她也一条条记。她说了句好，然后把那张纸收起来，折得很齐，放进包里。从那之后她再没提过崩溃两个字，像是把情绪收进了一个抽屉里，换成了一张清单。可你注意到了两件事：她那天晚上洗碗的时候，水开得很大，洗了很久；还有，你列那三条的时候，用的是自己的经验，不是她的处境。她照做了，做得也快，可那些事本来该她自己决定，你替她把顺序排好了，也顺手把她那部分念头一起排掉了。你后来想过，那三条如果没有你，她是不是也能自己列出来，也许能，也许要慢很多，但那才是她要的东西。你把那张草稿留了下来，没有给她，夹在自己那本书里，像是给自己留一个提醒。过了两天你把那张草稿又从书里抽出来看了一遍，拿笔划掉了原来那三条，重新写了三行，行与行之间留了空。你决定这一次把笔递给她。你把那张草稿夹进书里之后，那本书你就再没有翻过，可你记得是第几页。",
