        text: "你没接话。她说了一句半截的话，就那么停在空气里，你也没去把它接完，只是坐在原处，等她自己往下走。她坐了一会儿，忽然就哭了，声音压着，肩膀一耸一耸，眼泪掉在膝盖上，掉出一小片深色。你没递纸，也没说安慰的话，只是把客厅那盏最亮的灯关了，只留下一盏小的，然后坐回原处，陪着她。她哭了大概五分钟，自己停了，起身去洗手间洗了把脸。回来的时候像是没发生过一样，头发重新理好了，问你要不要一起吃点什么。你说好。那顿饭两个人话都不多，但气氛是松的，碗筷碰在一起的声音都比平时轻。她后来跟你提起那次，说那天要是有人劝她，她可能反而哭不住，会觉得自己的事被人当成了事，被架起来了；没人劝，哭完自己就过去了。你听了没说什么，只是把这句话记住了，记了很久。她那句哭完自己就过去了，你想了很久。你帮她的方式里，有多少是替她做，有多少是让她自己做，这条界线你一直没划清。那晚之后你开始注意，什么时候伸手，什么时候该把手收回来。那晚之后你留意到，她哭的时候声音比以前小，小到你在客厅几乎听不见。你把灯关了之后，在客厅又坐了一会儿，才起身回房，路过那间客房的时候放轻了脚步。",
