        label: '让管家接',
        keywords: ['管家接', '别人接', '转接'],
        cond: null,
        text: "你让管家接了。管家拿起电话，报了身份，语气客气，每一句都卡在规矩里，问什么答什么，多的一个字不说。你坐在旁边听着，听出对面先是试探，后来是警惕，最后没了声音。挂了电话，管家把话筒放回去，说了一句话：对方确认了咱们这边有第三方。你问什么意思。他说，意思是以后他们说话会更小心，这些事也不再是只对着那两个人，而是对着一个有背景的对手；有些人本来只想在暗处收钱，现在得重新掂量这件事的分量。你说这不是好事吗。管家顿了顿，说，是好事，也是把这件事往更大的地方推了一步，推大了，收场的方式也就跟着变了，原本能私下了结的，往后未必。你看着那部安静下来的电话，没再说话。当晚你又问了管家一句，对方还会不会再来。管家说会，但会换方式，也许不再打电话，改成别的地方出现。你问什么地方。他说，比如你不在意、但他们觉得你在意的那些地方。你把这句记了下来，列了一遍：学校、你家、她以前上班的那条街。列完你把纸折起来，忽然发现这张纸上没有一处是为你自己写的，全是那两个人才会去的地方。你问完那句之后，管家没有立刻回答，两个人站在门口安静了一会儿，谁也没有先说。",
