        text: "你站在门口，把上门的那两个人挡在了门框外面。他们穿得普通，话说得很熟，像是来过很多次，问的也不是你，是那个姓周的欠了多少、人在哪里、什么时候能见到人。其中一个人把手里的催告单举起来给你看，红色的，贴过很多次，边角都卷了，上面那个名字不是你的，你却记住了，记在了那页纸上。你没有让他们进门，也没有多问，只是重复一句话：人在屋里，事找我，别敲第二次。他们打量了你几眼，看了看你身后的屋子，记下了什么，走了，走得不快，像是还会再来，也像是先回去交差。楼道里的声控灯一盏盏灭下去，最后只剩你门口这一盏还亮着。你回头，看见她站在客厅中央，没坐下，两只手绞在一起，脸白得没什么血色。你说没事，走了。她点头，可肩膀一直没松下来，一直到夜里都没松。那天深夜，她把你家门内侧的鞋摆得整整齐齐，像是怕再有人从外面看见一屋子的乱，也像是只有把东西摆正，她才能睡得着。那天夜里她把门内侧的鞋摆正之后，又把玄关那盏灯留着没关，一直到你回房，那盏灯才灭。你回房之后听见她把玄关的灯关了，然后才回的自己屋。她点头的时候看了你一眼，那一眼不像谢，也不像怕，只是记住了门口站着的那个人是你。",
