        text: "你拦在车前。那是一辆很普通的黑色面包车，晚上停在小区北门外的辅路上，引擎没熄，车灯也没开，就那么黑着停在那里。你走过去的时候，车窗没有摇下来，隔着玻璃，你能看清副驾那个人把对讲机按灭的动作，很熟练，像是做过很多次，做得连头都没抬。你不喊，也不拍窗，只是站在车头正前方，让对方看得见你，也让你自己看得见对方，站定，不动。车里的人和车外的人僵了几秒，那几秒很长，长到你能听见自己呼吸的声音，也能听见雨点落在车顶上的声音。最后司机挂上挡，往后倒了一段，绕开你走了，走得不算快，像是给你留了一个看清楚的机会。你没有追，因为身边还站着一个放学回家的孩子，她刚才被安保叫住，站在原地，书包抱在怀里，一直没出声。你回头看她，她问你，是不是就是这辆车。你说是。她点点头，没有哭，也没有问别的，只是把书包抱得更紧了点。回去的路上她一直走在你半步后面，到了楼下才说了一句，你刚才站得挺直的。你没接话，因为你自己知道，那不是直，是绷的。那天夜里你让安保把门口的车又多留了一盏灯，灯亮了整夜，谁也没关。你上楼以后没有立刻睡，把今天的时间点、车牌、那个按灭对讲机的动作，一条一条写进本子。写完你翻到前面几页对比，发现这辆车出现的间隔在缩短，从一周一次，到三天一次，到今天。规律本身就是信息，说明有人在按一个节奏推这件事往前走。你把这一条单独圈出来，画了个箭头，箭头指向的空白处，你写不下任何字，因为你还不知道推这件事的人想要什么。",
