        text: "一封函出去，一份申请递上去，两条线同时压过去。律师那边走的是民事，警方那边走的是备案与协查，一条从纸面走，一条从系统走，看起来是两件事，实际指向的是同一批人的同一批动作。你把两份材料的时间掐在一起，让它们在同一天落下去。对方显然没料到你会同时动两条线，那几天原本规律的动静乱了：车换了，电话停了，中间人那边的口气也软了。你在纸上把两边的回执钉在一起，钉成一个文件夹，封面写着日期。花钱是真的花了不少，一笔律师费，一笔保全的手续费，加起来是你能承受的上限，但你没有犹豫。两条线同时走的好处，是对方不知道该先堵哪一头；坏处，是你自己也被拉成两半，白天盯律师的进度，晚上等警方的消息，常常一顿饭吃到一半就接电话。她看在眼里，有一次把碗往你面前推了推，说先吃。你说好，可筷子还是放下了。那阵子你瘦了点，她自己倒比前一阵稳，会替你记一些你忘了的事，比如哪份材料还差一个章，比如哪天该去银行。你后来想，这件事走到这一步，你已经不是一个人在推了。那天晚上你把两份回执放在一起核对，发现警方那边给出的一个日期，比律师函上的整整早了一周。这意味着对方的动作，早在你发函之前就开始了，也意味着你之前的判断没错：他们不是被你逼出来的，是自己按计划在走。你把这一周记下来，作为一种确认。确认完你没有轻松，因为知道得越多的人，越清楚自己面对的是什么。你合上文件夹，去厨房倒了杯水，看她们房间的灯一盏盏灭了，才回房。",
