        text: "你只发了函，没有惊动别的线。程序慢，但它有一个好处：程序上不失分。你没有让任何人抓到把柄，也没有给对方留下这个人急了的印象。函件一封一封出去，律师按部就班地推，对方的回应也在程序里，规规矩矩，看不出情绪。你有点不适应这种慢，因为你习惯了自己上手，可现在你只能等。等的过程里，她把家里的事重新理顺了一遍：账单、日用品、孩子的课程表，一样一样归置好，像是在给一段不知道多长的等待做准备。你看着这些，忽然明白，慢也有慢的用处——它给了她一个重新站起来的空间，而这个空间，是快给不了的。有一回你忍不住想再推一把，她把那页函件的回执递给你看，说该走的都走了，别乱。你收回了手。这种慢后来证明是对的：对方在程序里露了一次破绽，正是因为他们以为你只走这一条线。慢也有慢的代价。一个月后你才发现，对方拿这段时间做了一件事：把一笔最有价值的资产转了出去，转得合法、干净、查不出问题。律师说这在意料之中，程序类的事情，本来就防不住这种提前量。你没有怪任何人，只是把这件事也写进了那页纸。你开始明白，程序能给你的是公平，不是速度；而这件事里，时间和公平一样贵。",
