        text: "你说再看一年。你有一堆理由：证据还不全，孩子还在读书，风头还没过去，再等等也许有更好的办法。她把笔放下了，说好。那个好听得很轻，轻得像一张纸落在地上。她没有争，也没有问为什么，只是把那些准备好的材料收了起来，收进抽屉，压在下面。后来你发现，她再没有主动提过立案的事。有些决定，你说等，她就真的把它搁下了，搁到你自己都不好意思再提。那一年后来并没有等来更好的办法，只是把一件本来可以了结的事，又多拖了三百多天。那一年里，那件被搁下的事偶尔会浮上来，比如孩子问起父亲，比如催收又上门，比如过年。每到这种时候，她都不会再跟你提立案，只是自己安静一会儿，然后就过去了。你有时候想开口，说要不我们重新开始办。可你一想到当初是自己说的等，就说不出口。这件事最后没有变成争吵，也没有变成遗憾，它只是变成了一个你们都绕开的角落，绕着绕着，成了一个房间的形状。这件事之后，她跟你之间反而更少了一层客套。她不再跟你解释她的决定，也不再问你的意见。有时候她只是告诉你结果，然后就去忙了。你说不出这是亲近还是疏远，只知道你们都省了很多话。",
