        keywords: ['回信', '回', '写回去'],
        cond: null,
        text: "信不长，写了三页。你写完之后读了一遍，把最重的那句划掉了，换成了一个日期。你想，有些话在信里说出来太重，不如留一个日期，让她自己去想。写完你没有立刻寄，放在抽屉里搁了两天，第三天去邮局寄的。寄完你在邮局门口站了一会儿。你想，这封信大概要过很久才会到她手里，也可能她收到了也不会回，这些你都想过，还是寄了。有些事做的时候就不图结果，图的是自己心里那口气顺了。那口气顺了之后，你回去睡了一觉。那口气顺了之后，你回去睡了一觉。第二天她问你昨天去哪儿了，你说去寄了封信。她问给谁的。你说给一个人的，迟到了很久。她没再多问，只是把早饭往你面前推了推。那件事你没有解释，也不需要解释。你想，有些事你自己做完了，心里有个数就行，不用非得让谁见证。你后来再收到类似的信，处理的方式也不一样了，有时候回，有时候不回，但至少你知道自己为什么这么选。你把那封信放进抽屉，和别的放在一起。抽屉里的东西不多，可它们排在一起，像是把你这些年一些没说出口的事，都收在了同一个地方。有一回你整理抽屉，看了一遍，又原样放回去。你想，这些东西留着，不是等谁来读，是等你自己哪天想起来的时候，能有个地方找。你后来再没打开过那封信，可你知道它在。",
