        label: '收进抽屉',
        keywords: ['存档', '收着', '放着'],
        cond: null,
        text: "你把信收进了抽屉。有些东西不必回，留着就够了。抽屉里现在有几样东西：她给你的信，你写的那页纸，还有两张回执。你把它们放在一起，压得整整齐齐。后来你偶尔会打开抽屉看一眼，看完再关上。你想，人到了某个年纪，会发现很多事其实不需要处理，只需要放好。放好了，它就不闹了，你不会忘，也不会疼，它只是在那儿，占着一个小地方。后来抽屉里的东西又多了几样，你也没有再逐一看过。后来抽屉里的东西又多了几样，你也没有再逐一看过。你想，有些东西放久了就变成家具的一部分，你知道它在，平时不看，打扫的时候会挪一挪，挪完放回去。它不打扰你，也不提醒你，它只是占着那个位置。你觉得这样挺好。人活到某个时候，会需要几个这样的抽屉，专门用来放那些不处理也不扔的事，放好了，日子才走得下去。你想，这大概就是成年人的处理方式：不是解决，是安放，安放好了，也就过去了。你后来发现，自己这个抽屉越来越满，可心情越来越平。你想，人年轻时总想把每一件事都处理干净，处理不干净就难受；到了一定年纪才明白，大多数事处理不干净，能安放好就算本事。你把这条当经验，没有告诉谁。",
