        text: "你在阳台上烧了它。灰很轻，一下就散了，风一吹连灰都看不见。你站在阳台上看着最后一点火星灭掉，忽然觉得轻松了。有些东西留着是负担，不是舍不得，是不敢。烧掉之后你回屋，把阳台的门关上，洗了手。那天晚上你睡得很好，很久没有睡这么好。第二天的日子照常过，没有人知道那封信的事，也没有人问你最近有什么心事。你把这件事收得很干净，干净到后来你自己都很少想起来。你把这件事收得很干净，干净到后来你自己都很少想起来。有一回你在别的地方看到类似的东西，心里动了一下，很快就过去了。你想，烧掉一封信和留下它，说到底都是在处理自己，跟那封信本身没有太大关系。你选了烧，是因为你需要一个动作，让自己知道这件事翻篇了。这个动作做完，你就真的翻过去了。你没有后悔过。你后来遇到别的事，也用了类似的办法，有时候是烧，有时候是扔，有时候是走一趟。方式不同，道理一样，都是给一件事一个动作，让它有个结束。有一回你跟一个朋友说起这种办法，他说你这是自欺欺人。你说也许，可自欺欺人也比欺不了自己强。他笑了。你想，人活着总要有几个能骗过自己的办法，不然那些过不去的事，就真的过不去了。",
