        keywords: ['信周助手', '听她的'],
        cond: null,
        text: "那位姓周的助手话不多，但每一句都对得上一个具体的日期。你顺着她的线往下走了两步，发现她给的信息比助理的更新，也更准，准到你有点意外。她没有明说要你干什么，只是把该出现的时间、该在场的人，一样一样告诉你，像是递给你一张地图，走不走随你。你按她说的走了，走得很快，也确实拿到了别人没拿到的东西。可走完你才反应过来，她知道得太多、太准，本身就说明她站的那个位置不简单；你借她的线走了一段，也就等于让她知道你走到了哪里。你把这条线索收起来的时候犹豫了一下，因为你不确定这条线到底是递给你的，还是牵着你走的。有些事情，给你便利的人，往往也在收集你。事情结束以后，她调走了，走得很安静，没有告别。你在电梯里碰到过她一次，两个人点了点头，谁都没提那天。你后来偶尔会想，她当初为什么要帮你那一下，是顺水人情，还是另有打算，你想不清，也不打算再想。你只知道，从那次以后，你收下任何人的好意之前，都会先看一眼这个好意的来路。这个习惯帮你避过几次坑，也让你损失了几段本来可以更近的关系。得失之间，你选了稳。这个代价，你后来是认了的，只是偶尔在深夜翻来覆去的时候，会想一想另一条路是什么样子。",
