        text: "你按自己的判断走，谁都没有问。助理提醒过你一次，你挥手说知道了；那位姓周的助手也发过消息，你看了一眼，没回。你觉得多问多错，不如自己拿主意，反正这些年在公司里也是这么过来的。那几天你走得很快，事情也办得利落，只是身边慢慢安静了下来，没有人再往你桌上放东西，也没有人再在你经过的时候提一句。等到一个细节出了岔子，你才想起来，那两个本可以提醒你的人，早就把嘴闭上了。没有人提醒你，也没有人替你挡，这不是因为他们不帮你，是因为你先关上了那扇门。你把这件事记在心里，后来再遇到关键的关口，你学会了一件事：可以不采纳，但不要不给别人说话的机会。那阵子你确实清静了，清静到有点享受。一个人扛事的效率很高，不用解释，不用协调，想怎么走就怎么走。可效率不能代替信息，你走得快，是因为你看不见路上那些本来会拦住你的东西。直到某个关口，你才发现自己手里少了一份谁都该知道的东西，而那份东西，本来有人要给你。你没有回头去找他们，因为找也找不回来了。你只是从那以后多了一条习惯：再忙，也留一个人能说话。这条习惯后来救过你一次，让你在一个快要踩空的关口，被一句话拉了回来。",
