        text: "雷声落下来的时候她抓住了你的袖子，抓得很紧，指甲隔着布料掐进你的手臂。你说去睡吧，把手抽了出来，抽的时候用了点力。她说了句对不起，很小声，说完把手缩回去，抱在胸前，像是怕它再自己伸出来。你退开一步，给她让出路。她低头沿着墙根走回房间，脚步很轻，房门合上时几乎没有声音。你站在原地，手臂上那几处被掐过的地方还留着一点热。窗外又是一道闪电，把整个客厅照亮了一瞬，你看见茶几上她刚才没喝完的半杯水，杯壁上有她手指按过的痕。那一夜你没睡好，几次听见隔壁有极轻的响动，又很快安静下去。第二天早上她照常出来，什么也没提，只是在你递给她牛奶的时候，手没有像往常一样接稳，洒了一点在桌上。她自己拿纸擦干净，一句话也没说。你们之间那种客气，从那天起又厚了一层。过了一周，她半夜起来喝水，在客厅撞见你，两个人都停了一下。她想说什么，最后只说了句，那天的雷声真大。你说嗯。她端着水回房，走到门口又说了一句，我知道你也不是故意的。这句话说得很轻，轻到你可以当成没听见。你听见了。你想解释几句，又觉得解释只会让那几处掐痕更清楚。你最终什么都没说。她从那天起确实不那么怕雷了，可你也知道，那不是因为不怕，是因为学会了不在你面前怕。",
