        text: "她是自己走过来的，话说得很直，直得不用你猜。她坐到你身边，先问了一句你现在是不是还愿意，你说愿意，她就没再问第二遍。你伸手的时候，她的肩先是绷着，随后慢慢松开，像是卸下了一件穿了很久的、不合身的外衣。这一夜没有谁在赶路。她起初还有些生疏，像是不太记得怎么被人这样对待，动作里带着试探；你没有急，只是让她自己找到那个可以停下来的位置。窗外的灯明明灭灭地映在墙上，她的呼吸一点点乱了，又一点点匀了，中间她叫过你的名字，很短，像确认你还在，你应了，她就更近地贴过来。她身上有很淡的皂角味，锁骨那里的皮肤是凉的，贴着贴着就热了。后来两个人都安静下来，她躺在那里，手指还搭在你手臂上，没有挪开。你替她把额前的头发拨到一边，她闭着眼笑了一下，没有睁眼。这一夜过去，有些东西不一样了，她说不上来是哪里，你也没让她说。第二天她起来，比平时更没有防备，也更是她自己。第二天她没有提那一夜，也没有回避，只是在做早饭的时候，把两个蛋都煎成了溏心的，一个给你，一个给自己。她吃得比平时慢。你坐在她对面，看着晨光一点一点爬上她的手背，忽然觉得昨夜的一切都落在了实处，落进了这样一顿寻常的早饭里。她抬头看你一眼，问你今天忙不忙。你说不忙。她哦了一声，继续吃。有些关系往前走一步，动静反而更小了。",
