        text: "三个人一起去的。老小区三栋三楼东户，门锁换过了，新的，和整栋楼都不一样。站在楼下的时候，谁都没有先抬头，像是都知道那三扇窗里没有一盏灯是给他们的。她母亲走在最前面，走得很快，到了单元门口又停下来等。若宁走在中间，一直看着地上。上楼的时候，楼梯间的声控灯一层层亮起来，又一层层灭下去。到了门口，敲了很久，没人应。她母亲把手贴在门上，站了一分多钟。若宁站在后面，忽然说了一句，我们不进去行不行。她母亲回过头看她，看了很久，最后说，行。三个人就那样下了楼。回去的路上谁都没说话，可比来的时候，好像近了一点。回去的路上她母亲一直在看手机，看那条已经停了三天的消息。若宁坐在后座，忽然说了一句，那个人是不是不会再回来了。她母亲没有回头，说不知道。若宁哦了一声，把窗户摇下去一道缝，让风进来。你从后视镜里看她们两个，一个看着手机，一个看着窗外，中间隔着一个人的距离。那趟路开了很久，谁都没有再说话，可比在城市里的许多天，都要安静，也都要近。下楼的时候她走在你和她母亲中间，三个人的脚步后来慢慢齐了，谁也没说话。楼下的风比楼道里冷，你把外套的拉链拉到了顶。",
