        text: "复查结果没问题。你带她出去吃了一顿，找了家安静的馆子。她吃得比平时多，中间还主动要了一份甜点。结账的时候她抢着看了眼账单，看完没说话，只是把账单推回给你，说下次她请。你说好。那天回去的路上她走得比平时慢，像是舍不得这顿饭结束。你问她今天开不开心。她想了想，说开心，然后就笑了。这是这几个月里，你第一次看见她笑得不带别的东西。到家她先去洗了个澡，出来的时候头发吹得半干，坐在客厅看了会儿电视才回房。那一晚家里的灯关得比往常晚一点。回去的路上她坐在副驾，把窗户摇下一条缝，让夜里的风进来。她忽然说，其实她最怕的不是生病，是生病的时候还得自己一个人去医院。你说以后不会了。她嗯了一声，没有再说话，但那只放在膝盖上的手，慢慢松开了。那晚之后，她开始在饭桌上说一些无关紧要的小事，学校里谁跟谁闹了别扭，哪门课的老师讲课有意思。都是些不相干的事，可你听得出来，她在试着把这个家当成一个可以说话的地方。你想，一个人愿意在饭桌上说废话，是因为她终于觉得这顿饭不是欠谁的。那天吃完饭回来，她在车上把下次我请一直记着。过了两周，她用自己打工攒的钱请你喝了杯茶，很便宜的那种，两个人坐在路边喝完的。你说好喝。她笑，说下次请贵的。你说不用，这个就挺好。她没再坚持，只是把那家店的名字记住了，像是给自己留了一个以后可以再去的地方。",
