        text: "你等着别人来找你。等了两周，发现该来的会已经开完了，没通知你。你去问，人家说以为你不关心这块。你说我在忙别的。人家说忙是忙，但这种事你不来，我们就当你不要。你愣在那里，第一次发现，原来不表态也是一种表态，而且在别人眼里，这种表态等同于放弃。你把这件事记下来，从此不轻易让任何一个会少了你的名字。可你也发现，光在场不够，还得说话，于是你开始在会前准备两句。这个过程不短，可它比任何一次冲动都稳。你后来在会上说话，从来不多，可每一句都有人记。有一回你提的一个建议被采纳了，散会后一个比你资历老的人走过来说，你这个想法不错，以前怎么不说。你说以前没想到。他说以后多想。你点头。你知道，从那天起，你在这间屋子里的位置，变了一点，变得不大，可够你往前走一步。有些东西只有站过那个位置的人，才知道它是怎么一点点来的。你把这句话说完，那个新同事没再说什么。过了几个月他也在会上开始说话，说得很小心，可确实在说。你看见了，没有指点，因为你知道，这种事指点不来，得他自己去撞那一下，撞完了他才知道那两句该怎么说。你后来把这件事讲给一个新来的同事听，他听完说，这么点事也要想这么久。你说对，以前我也不懂。有些东西只有站过那个位置的人，才知道它是怎么一点点来的，也才知道，为什么有人一辈子就停在名单上，没变成会里被点名的那个人。他没接话，过了几个月，你看见他也开始会在会前准备两句了。",
