        text: "你把嫂子和侄女，家里遇到点难处，这句话说得很自然，说得像是随口一提。同一晚，那边抛过来的话题你一个没落，接得稳，接得准，话不多，可每一句都在点上。散场的时候有人拍你的肩，说你有担当。你笑了笑。回家的车上你想，这一晚你做了两件事，一件是承认了她们的处境，一件是替自己拿了分。两件事你都做得不亏，可你把它们放在同一个晚上，就注定要让其中一件打一点折扣。你不确定她们知道以后会怎么想，只是把这件事先压下了。过了几天她母亲在饭桌上提了一句，说听人说你那天在饭局上提到我们了。你说嗯，随口说的。她说哦，没有再说别的。你想解释一下那不是随口，又觉得解释只会更重。有些事就是这样，你做的时候觉得两边都不亏，落到对方那里，就成了你替她们做了主。这件事之后你再遇到类似的场面，凡是涉及她们的，都会先想一想，再说出口。后来的事情证明，那一晚两件事同时做，你并没有吃亏。饭局上的人记住了你，家里的人也没有真的计较，她们甚至没有追问那场饭局讲了什么。可你自己知道，那一晚你其实做了选择：你把她们的处境拿出来当了一个话题，哪怕只是半句，那也是替她们做的决定。这件事后来没有发酵，不等于它没发生。你把它记下来，不是自责，是提醒自己，下一次再遇到这种场合，先把她们的位置放好，再决定自己说什么。",
