        text: "你托人问了那个男生的基本情况，成绩、家里的情况、有没有别的乱七八糟的事，问完确认没问题，才表态支持。她事后知道了你查过，也没生气，只说了一句你挺认真。你说该认真。她说那要是查出来不好呢。你说那我也会告诉你，然后你自己定。她想了想，说行。这句话之后，你们之间关于这件事的对话就结束了。你后来想，她要的其实不是你的同意，是你别瞒着她替她做决定，这两样她分得很清楚。她要的其实不是你的同意，是你别瞒着她替她做决定，这两样她分得很清楚。后来遇到别的事，她也用同样的方式跟你打交道：先告诉你想做什么，等你说知道了，她再去做。你发现这样很好，省事，也不伤感情。有一回你忍不住替她做了个决定，她当时没说什么，事后跟你讲了一句，下次我自己说。你说好。从那以后你没有再犯，因为她只提醒一次。你想，一个家能维持下去，靠的往往不是感情有多深，是这种不唠叨的默契。后来你们之间很多事都是这么办的。她做砸了一件事，自己来说，你说知道了，下次注意，就完了；你做错一件事，也跟她讲一句，她也说知道了。你们谁都不翻旧账，因为翻旧账最伤人，也最没用。这个规矩你们谁都没立，可一直都守着。",
