        text: "你说别麻烦别人。话说得委婉，可她听懂了。从那以后她不再提这个人，难题也自己扛了，扛不动就空着，也不来问你。你想，你本来是怕她吃亏，可你做出来的效果，是让她把一扇本来开着的门自己关上了。有一回她做完作业在阳台上站了很久，你去问她想什么，她说没什么。你知道有什么，只是她不想跟你说了。你把这件事记着，明白关心用错了方式，就成了管，而管这个字，一旦沾上，就很难再松开。你把这件事记着，明白关心用错了方式，就成了管，而管这个字，一旦沾上，就很难再松开。后来你学乖了，遇到她的事，先问一句你想怎么办，再决定要不要说话。有时候她说的跟你想的不一样，你也不拦，让她自己去试。试完回来，她自己会说这次想错在哪里。你发现，人只有自己走一趟，才知道路是弯的还是直的，你在旁边说得再准，那也是你的路，不是她的。后来她的事你都不再替她拿主意，只在她问的时候说两句。有一回她自己报了一个很难的班，报了之后才告诉你。你说知道了。她说你不拦我。我说拦得住吗。她笑了，说拦不住。你后来看她学得很苦，也没劝她退。半年后她学完了，回来跟你说还行。你想，这就叫长出来了，不是被扶起来的，是自己站的。你把这个记着，当作这半年里最值的一件事。",
