        text: "你绕了一级。事情当天就定了，但这位老人的记性一向很好。后来有一次你在别的事上需要他那一票，他给了一个既不反对也不支持的态度，把事拖了两个月。你把这两个月记着，明白绕过去容易，绕过去之后要还的，慢慢就来了。你没有后悔，因为当时那件事必须当天定。可你把这条经验留着：能不得罪的人，别得罪，尤其那种坐在那里不动、但你迟早要用到的人。后来你花了很长时间去修这一段，修得很费劲，因为老人的记性不是记仇，是记规矩，你当初坏了规矩，他就要用规矩还你一次。你把这一课记住，用来管住自己后来几次想绕过去的冲动，有一次你忍住了，那次后来证明，忍住是对的。你把这两次放在一起对照：一次绕了，省了当天的功夫，欠了两个月的；一次忍了，多花了一周，把事情办得干干净净。后来凡是要过会的事，你都先问自己一句：这个人我以后还用不用。用，就不绕，多花几天也值；不用，就绕，绕得干净利落。这个判断你做得越来越快，快到你都不用想那两个月了，可那两个月一直在，它成了你判断里的一部分。你想，人就是这样被一件事一件事磨出来的，磨到最后，你自己都分不清哪些道理是你学的，哪些是你被磨的。",
