        cond: null,
        text: "你们谁也没提这件事，日子照旧过。不推进也是一种决定，只是没人负责。你偶尔会收到她的一条消息，说的都是公事，你也就按公事回。这样的关系可以维持很久，久到你们都忘了当初为什么没有把它推到下一步。你后来想，人对一件事最省力的处理方式，就是让它停在那里不动，不动就没有成本，也没有结果，它只是占着一个位置，一直占着。你后来发现，自己手机里有几个这样的联系人。你后来发现，自己手机里有几个这样的联系人，都是一些停在那里不动的关系，不删，也不联系。有一年换手机，你把其中一半都没同步过去，也没有觉得少了什么。你想，人这一辈子要处理的关系太多，大部分其实不需要处理，它们自己会随着时间淡掉，你只要不动它，它就自己走了。这个道理你用了很久才接受，接受之后，你少了很多不必要的告别。有一年你清理手机，一口气删了几十个联系人，删的时候没有停顿。你想，人和人之间其实大部分关系都是这样的，它不结束，也不继续，就那么在时间里泡着，泡到某一天你连它是不是还在都不确定。你不觉得这样凉薄，因为你自己也是别人手机里那些不动的关系之一。",
